// === Tab: mySketch ===

const particles = [];
const step = 8;
const pointSize = 6
const ease = 0.05; // Controls the returning speed

function setup() {
	createCanvas(1000, 600);

	for (let x = 0; x < width; x += step) {
		for (let y = 0; y < height; y += step) {
			const p = new Particle(
				x + random(-3, ),
				y + random(-3, 3),
				pointSize
			)
			particles.push(p)
		}
	}
}

function draw() {
	background("rgb(68,13,208)");

	particles.forEach((particle) => {
		particle.update();
		particle.show(pointSize);
	})
}

// === Tab: Particle ===
class Particle {
  constructor(x, y, size) {
    this.x = this.ox = x;
    this.y = this.oy = y;
		this.size = size
  }

  update() {
		var p = {x: (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), y: (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))}
    const d = dist(this.x, this.y, p.x, p.y);
    const a = atan2(this.y - p.y, this.x - p.x);
    const f = 5*smoothstep(120, 0, d);

    if (d < 200) {
      // Apply interaction force if within range
      this.x += cos(a) * f;
      this.y += sin(a) * f;
    }

    // Return to original position with easing
    this.x += (this.ox - this.x) * ease;
    this.y += (this.oy - this.y) * ease;
  }

  show(pointSize) {
		stroke(0)
		strokeWeight(this.size)
    point(this.x, this.y);
  }
}


// === Tab: Math ===
const smoothstep = (edge0, edge1, x) => {
	x = constrain((x - edge0) / (edge1 - edge0), 0, 1)
	return x * x * (3 - 2 * x)
}

